/**
 * The `argparse` subset the reference program uses: long flags that each take
 * one `int` argument, all required, plus the automatic `-h/--help`.
 *
 * Error wording, exit statuses (2 for a usage error, 0 for `--help`), option
 * abbreviation, `--flag=value` syntax, negative numbers as values and the help
 * layout all follow the reference implementation, because any of them can end
 * up in the compared output.
 */

import { SystemExit } from './errors.mjs';
import { pyRepr, writeStderr, writeStdout } from './pytext.mjs';
import { helpWidth, wrapText } from './textwrap.mjs';

const USAGE_PREFIX = 'usage: ';
const MAX_HELP_POSITION = 24;
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, metavar, type, typeName, required, help, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.metavar = metavar;
    this.type = type;
    this.typeName = typeName;
    this.required = required ?? false;
    this.help = help;
    this.isHelp = isHelp ?? false;
  }

  /** `_get_action_name`: option strings joined by "/". */
  get name() {
    return this.optionStrings.join('/');
  }

  /** How the action appears in the usage line and the options list. */
  get invocation() {
    if (this.isHelp) return this.optionStrings.join(', ');
    return `${this.optionStrings[0]} ${this.metavar}`;
  }

  get usagePart() {
    const part = this.isHelp ? this.optionStrings[0] : this.invocation;
    return this.required ? part : `[${part}]`;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.addArgument(['-h', '--help'], {
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const primary = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = primary.replace(/^-+/, '').replace(/-/g, '_');
    this.actions.push(new Action({
      optionStrings,
      dest,
      metavar: options.metavar ?? dest.toUpperCase(),
      type: options.type,
      typeName: options.typeName,
      required: options.required,
      help: options.help,
      isHelp: options.isHelp,
    }));
  }

  /** All option strings, mapped to their action. */
  optionIndex() {
    const index = new Map();
    for (const action of this.actions) {
      for (const flag of action.optionStrings) index.set(flag, action);
    }
    return index;
  }

  /**
   * Classifies a token the way `_parse_optional` does: `null` for a value,
   * otherwise the matching action (or `null` action for an unknown flag).
   */
  classify(token) {
    if (token.length === 0) return null;
    if (!token.startsWith('-')) return null;

    const index = this.optionIndex();
    const exact = index.get(token);
    if (exact !== undefined) return { action: exact, flag: token, value: undefined };
    if (token.length === 1) return null;

    if (token.includes('=')) {
      const separator = token.indexOf('=');
      const flag = token.slice(0, separator);
      const withValue = index.get(flag);
      if (withValue !== undefined) {
        return { action: withValue, flag, value: token.slice(separator + 1) };
      }
    }

    const abbreviations = this.matchAbbreviation(token);
    if (abbreviations.length > 1) {
      const candidates = abbreviations.map((match) => match.flag).join(', ');
      this.error(`ambiguous option: ${token} could match ${candidates}`);
    }
    if (abbreviations.length === 1) return abbreviations[0];

    // A negative number is a value, since no flag here looks like one.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;
    return { action: null, flag: token, value: undefined };
  }

  /** `_get_option_tuples`: unique prefix matching for long options. */
  matchAbbreviation(token) {
    const separator = token.indexOf('=');
    const prefix = separator === -1 ? token : token.slice(0, separator);
    const explicit = separator === -1 ? undefined : token.slice(separator + 1);
    const matches = [];
    for (const [flag, action] of this.optionIndex()) {
      if (flag.startsWith(prefix) && flag !== prefix) {
        matches.push({ action, flag, value: explicit });
      }
    }
    return matches;
  }

  parseArgs(argv) {
    const namespace = {};
    const seen = new Set();
    const extras = [];

    for (let position = 0; position < argv.length; position += 1) {
      const token = argv[position];
      const parsed = this.classify(token);

      if (parsed === null) {
        extras.push(token);
        continue;
      }
      if (parsed.action === null) {
        extras.push(token);
        continue;
      }
      if (parsed.action.isHelp) {
        this.printHelp();
        throw new SystemExit(0);
      }

      let raw = parsed.value;
      if (raw === undefined) {
        const next = position + 1 < argv.length ? argv[position + 1] : undefined;
        if (next === undefined || this.classify(next) !== null) {
          this.error(`argument ${parsed.action.name}: expected one argument`);
        }
        raw = next;
        position += 1;
      }
      namespace[parsed.action.dest] = this.convert(parsed.action, raw);
      seen.add(parsed.action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  convert(action, raw) {
    if (action.type === undefined) return raw;
    try {
      return action.type(raw);
    } catch {
      this.error(
        `argument ${action.name}: invalid ${action.typeName} value: ${pyRepr(raw)}`,
      );
      return undefined;
    }
  }

  formatUsage() {
    const parts = this.actions.map((action) => action.usagePart);
    const width = helpWidth();
    const singleLine = `${this.prog} ${parts.join(' ')}`;
    if (USAGE_PREFIX.length + singleLine.length <= width) {
      return `${USAGE_PREFIX}${singleLine}\n`;
    }

    const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
    const lines = layoutUsageLines([this.prog, ...parts], indent, width, USAGE_PREFIX);
    return `${USAGE_PREFIX}${lines.join('\n')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => action.invocation);
    const maxLength = Math.max(...invocations.map((text) => text.length)) + 2;
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - 4;
    const textWidth = Math.max(helpWidth() - helpPosition, 11);

    let body = '';
    for (const action of this.actions) {
      const invocation = action.invocation;
      if (!action.help) {
        body += `  ${invocation}\n`;
        continue;
      }
      const helpLines = wrapText(action.help, textWidth);
      if (invocation.length <= actionWidth) {
        body += `  ${invocation.padEnd(actionWidth)}  ${helpLines[0]}\n`;
      } else {
        body += `  ${invocation}\n${' '.repeat(helpPosition)}${helpLines[0]}\n`;
      }
      for (const line of helpLines.slice(1)) {
        body += `${' '.repeat(helpPosition)}${line}\n`;
      }
    }
    return `${this.formatUsage()}\noptions:\n${body}`;
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** Usage on stderr, then `SystemExit(2)`. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }
}

/** `HelpFormatter._format_usage.get_lines`, keeping the same line budget. */
function layoutUsageLines(parts, indent, width, prefix) {
  const lines = [];
  let current = [];
  let length = prefix.length - 1;
  for (const part of parts) {
    if (length + 1 + part.length > width && current.length > 0) {
      lines.push(current.join(' '));
      current = [];
      length = indent.length - 1;
    }
    current.push(part);
    length += 1 + part.length;
  }
  if (current.length > 0) lines.push(current.join(' '));
  return lines.map((line, position) => (position === 0 ? line : `${indent}${line}`));
}

